type AutoPromise<T> = Promise<Awaited<T>>;
import {
	cyan, black, red, green, magenta, yellow,
	stripAnsiCode,
	} from '@std/fmt/colors'
import {
	Listr, ListrTask, ListrRenderer, ListrTaskEventType,
	ListrRendererSelection, ListrLogLevels, ListrDefaultRendererLogLevels,
	ListrEventManager, ListrTaskObject, ListrLogger, DefaultRenderer,
	} from 'listr2'

import {hash} from 'datatypes'

const listrLogger = new ListrLogger({useIcons: false})

// ---------------------------------------------------------------------------

export const LOG = (msg: string): void => {

	listrLogger.log(ListrLogLevels.STARTED, msg)
	return
}

// ---------------------------------------------------------------------------
// ASYNC

export const runTasks = async <T=hash,>(
		lTasks: ListrTask<T>[],
		ctx: T
		): AutoPromise<T> => {

	const listr = new Listr<T>(lTasks, {
		concurrent: true,
		exitOnError: false,
		forceUnicode: true,
		ctx,
		renderer: 'default',
		rendererOptions: {
			icon: {
				// Removes icons for all states (PENDING, SUCCESS, FAILED, etc.)
				PENDING: () => '⏳',
				COMPLETED: () => '✅',
				FAILED: () => '❌',
				RETRY: '🔄',
				SKIPPED_WITH_COLLAPSE: '⏩',
				SKIPPED_WITHOUT_COLLAPSE: '⏩',
				ROLLING_BACK: '↩️',
				ROLLED_BACK: '↩️'
				},
			color: {
				FAILED: (message?: string) => red(message || ''),
				COMPLETED: (message?: string) => green(message || ''),
				ROLLED_BACK: (message?: string) => magenta(message || '')
				}
			}
		})
	await listr.run()
	return await ctx
}

